 			case 'none':
 			case 'treble+8':
 			case 'treble-8':
 				break;
 			case 'bass3':
 			case 'bass':
 			case 'bass+8':
 			case 'bass-8':
 			case 'bass+16':
 			case 'bass-16':
 				mid = -12;
 				break;
 			case 'tenor':
 				mid = -8;
 				break;
 			case 'alto2':
 			case 'alto1':
 			case 'alto':
 			case 'alto+8':
 			case 'alto-8':
 				mid = -6;
 				break;
 		}
 		return mid + oct;
 	}
 
