 	addPosToKey(clef: ClefElement, key: KeySigElement): void {
 		if (!clef || !key || !key.accidentals) return;
 		const mid = clef.verticalPos;
 		for (let acc of key.accidentals) {
 			let pitch = this.pitches[acc.note as PitchKey];
 			if (pitch !== undefined) {
