 		}
 		if (this.lines[this.lineNum] === undefined) createLine(params);
 		else if (this.lines[this.lineNum].staff === undefined) {
 			this.lineNum++;
 			this.startNewLine(params);
 		} else if (this.lines[this.lineNum].staff[this.staffNum] === undefined)
