 					return;
 				}
 			}
 		}
 		this.lineNum = i;
 	};
 	/**
 	* 新增元資料文字。
 	* @param key 元資料鍵。
 	* @param value 元資料值。
 	*/
 	addMetaText(key: string, value: string): void {
 		if (this.metaText[key] === undefined)
 			this.metaText[key] = value;
 		else
 			this.metaText[key] += "\n" + value;
 	}
