 			}
 
 			const gracenotes: NOTES_Element[] = [];
 			let ii = 0;
 			let inTie = false;
 			while (ii < gra[1].length) {
 				const note = this.getCoreNote(gra[1], ii, {}, false);
 				if (note !== null) {
 					gracenotes.push(note as NOTES_Element);
 
 					if (inTie) {
 						note.endTie = true;
 						inTie = false;
 					}
 					if (note.startTie) {
