 	w: number = 0;
 	y: number = 0;
 	i: number = 0;
 	ii: number;
 	durationindex: number = 0;
 	duplicate: boolean = false;
 	startx: number;
 	minx: number;
 	nextminx: number;
 	nextx: number;
 	spacingunits: number;
 	voicenumber: number;
 	voicetotal: number;
 	barfrom: boolean;
 	barto: boolean;
 	barbottom: number;
 	header: string;
 	staff: StaffLayoutInfo;
 	clef: ClefType = 'treble';
 	jianpuOctave?: number;
 	jianpuKey?: KeySigElement;
 
 	constructor(y: number, voicenumber: number, voicetotal: number) {
 		this.y = y;
