 		}
 		this.nextx = x;
 		// contribute to staff y position
 		if (this.staff) {
 			this.staff.highest = Math.max(child.top, this.staff.highest);
 			this.staff.lowest = Math.min(child.bottom, this.staff.lowest);
 		}
