 		}
 		let removeLater: boolean = !el;
 		if (!el)
 			el = this.text(attr.x, attr.y, text, attr);
 		let size;
 		try {
 			size = el.getBBox();
 			if (isNaN(size.height) || !size.height)
 				size = this.guessWidth(text, attr);
 			else
 				size = { width: size.width, height: size.height };
 		} catch (ex) {
 			size = this.guessWidth(text, attr);
 		}
 		if (removeLater) {
 			if (this.currentGroup.length > 0)
