 				else if (key === 'klass')
 					el.setAttributeNS(null, "class", attr[key]);
 				else if (attr[key] !== undefined)
 					el.setAttributeNS(null, key, attr[key]);
 			}
 		}
 		this.append(el);
 		return el;
 	};
 
